INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '春节', '中华民族最隆重的传统佳节，齐鲁大地家家贴春联、守岁、拜年。', '春节是山东民间最隆重的传统节日。进入腊月，家家户户便开始忙年：二十三糖瓜粘祭灶王，二十四扫房子，蒸年糕、炸耦合、备年货。除夕夜全家团圆守岁，吃饺子、放鞭炮；初一清晨着新衣拜年，长辈给晚辈压岁钱。山东各地春节期间还有舞龙舞狮、踩高跷、跑旱船等民间扮玩活动，一直热闹到正月十五。', NULL, NULL, NULL, '["传统节庆", "全域", "农历正月"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历正月初一', '春节起源于上古时代的岁首祈年祭祀活动，汉武帝时期正式确定以农历正月初一为岁首，沿袭两千余年。', '祭灶、扫尘、贴春联、挂年画、守岁、包饺子、拜年、发压岁钱、舞龙舞狮。', '饺子（更岁交子之意）、年糕（年年高）、炸货、花饽饽（胶东地区尤盛）。' FROM cultural_item WHERE category = 'festival' AND title = '春节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '元宵节', '赏花灯、吃元宵、猜灯谜，山东各地灯会争奇斗艳。', '正月十五元宵节是春节的压轴大戏。山东各地张灯结彩，济南趵突泉、淄博周村、潍坊杨家埠等地灯会久负盛名。民间有踩高跷、扭秧歌、耍龙灯、划旱船等扮玩活动，周村芯子更是国家级非遗。家家吃元宵（北方称''滚''元宵），寓意团圆美满。', NULL, NULL, NULL, '["传统节庆", "全域", "灯会"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历正月十五', '元宵节源于汉代祭祀太一神的传统，汉明帝提倡佛教后燃灯表佛，逐渐演变为民间灯节。', '赏花灯、猜灯谜、吃元宵、踩高跷、舞龙灯、放烟花。', '元宵（糯米滚制，馅料多样，北方摇制与南方包制不同）。' FROM cultural_item WHERE category = 'festival' AND title = '元宵节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '二月二·龙抬头', '剃龙头、吃炒豆，祈盼一年风调雨顺、鸿运当头。', '农历二月初二俗称''龙抬头''，山东民间认为这天龙王升天、行云布雨，标志着春耕开始。这一天有理发的习俗，谓之''剃龙头''，寓意辞旧迎新、鸿运当头。家家户户炒豆子、炒棋子块（面旗子），称为''炒蝎子爪''，据说可免除虫害。部分地区还有打粮囤、引龙回等祈丰年习俗。', NULL, NULL, NULL, '["传统节庆", "全域", "春耕"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历二月初二', '源于古人对东方苍龙七宿星象的观测，仲春时节龙角星从地平线升起，故称龙抬头。', '剃龙头、炒豆子、打粮囤（用草木灰在院中画圈祈丰年）、忌动针线（恐伤龙目）。', '炒黄豆、炒棋子块、春饼（龙鳞）、面条（龙须）。' FROM cultural_item WHERE category = 'festival' AND title = '二月二·龙抬头' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '清明节', '扫墓祭祖、踏青插柳，慎终追远与春日游赏并存。', '清明节兼具自然节气与人文节日双重内涵。山东民间清明要扫墓祭祖，添土圆坟、焚烧纸钱、敬献供品，表达对先人的追思。同时清明正值春回大地，人们踏青郊游、放风筝、荡秋千、插柳戴柳。鲁西南一带还有清明吃鸡蛋、吃冷食的旧俗，部分地区保留寒食遗风。', NULL, NULL, NULL, '["传统节庆", "全域", "祭祖"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '公历4月5日前后', '清明本为二十四节气之一，后与寒食节（纪念介子推）、上巳节融合，唐代起成为祭祖扫墓的固定节日。', '扫墓祭祖、添土圆坟、踏青、放风筝、插柳、荡秋千。', '鸡蛋（画蛋、碰蛋）、冷饽饽、青团（近年自南方传入）。' FROM cultural_item WHERE category = 'festival' AND title = '清明节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '端午节', '包粽子、插艾草、系五彩绳，驱邪避疫祈福纳祥。', '五月初五端午节，山东民间家家户户门口插艾草、菖蒲，孩童手腕系五彩丝线（谓之''拴五色线''），佩戴香荷包，以驱五毒、避瘟疫。鲁南微山湖、东平湖一带水乡有赛龙舟之俗。家家包粽子，山东粽子多为黄米或糯米加大枣，甜口为主。', NULL, NULL, NULL, '["传统节庆", "全域", "驱疫"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历五月初五', '端午节起源有纪念屈原、伍子胥、曹娥等多种说法，亦与上古夏至祛病防疫的时令习俗相关。', '插艾草菖蒲、系五彩绳、佩香囊、包粽子、赛龙舟（水乡地区）、沐兰汤。', '大枣粽子（黄米/糯米）、煮鸡蛋、雄黄酒（旧俗，今多不饮）。' FROM cultural_item WHERE category = 'festival' AND title = '端午节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '七夕节', '牛郎织女鹊桥相会，山东沂源被誉为牛郎织女传说之乡。', '七夕又称乞巧节，源于牛郎织女的美丽传说。山东沂源县燕崖镇保留着织女洞与牛郎庙隔河相望的独特景观，被认定为牛郎织女传说的重要传承地。旧时少女在这天晚上穿针乞巧、拜织女，祈求心灵手巧、婚姻美满。如今七夕已成为象征爱情的中国情人节。', NULL, NULL, NULL, '["传统节庆", "全域", "爱情"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历七月初七', '源于上古星宿崇拜（牵牛星、织女星），汉代定型为牛郎织女一年一度鹊桥相会的爱情传说。', '穿针乞巧、拜织女、喜蛛应巧、听悄悄话（葡萄架下听牛郎织女夜话）。', '巧果（七巧果子，油炸面食小点心）、花瓜。' FROM cultural_item WHERE category = 'festival' AND title = '七夕节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '中秋节', '赏月团圆、吃月饼，仲秋时节庆丰收。', '八月十五中秋节，正值三秋大忙之后的丰收时节。山东民间家家户户备月饼、瓜果祭月、赏月，讲究全家团圆，出嫁的女儿也要回娘家团聚。部分地区有''男不拜月、女不祭灶''的旧俗。胶东一带做''月糕''、蒸''月鼓''，寄托团圆美满之意。中秋前后正值黄河口大闸蟹、莱阳梨等物产上市，节日餐桌格外丰盛。', NULL, NULL, NULL, '["传统节庆", "全域", "团圆"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历八月十五', '中秋节源于古代秋夕祭月之礼，唐代成为固定节日，宋代盛行，明清时与春节齐名。', '祭月、赏月、吃月饼、全家团圆宴、走亲戚。', '月饼、月糕、瓜果（葡萄、梨、石榴）、时令河海鲜。' FROM cultural_item WHERE category = 'festival' AND title = '中秋节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '重阳节', '登高望远、赏菊敬老，千佛山重阳山会人潮如织。', '九月初九重阳节，''九九''谐音''久久''，寓长寿之意。山东民间有登高、赏菊、饮菊花酒、插茱萸的习俗，济南千佛山重阳山会自元代延续至今，是齐鲁重阳民俗的代表。1989年我国将重阳节定为老人节，各地开展敬老爱老活动，传统登高节与现代敬老节融为一体。', NULL, NULL, NULL, '["传统节庆", "全域", "敬老"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历九月初九', '重阳节源于先秦秋收祭天、祭祖活动，汉代已有登高佩茱萸习俗，唐代正式定为节日。', '登高、赏菊、插茱萸、饮菊花酒、敬老祝寿、赶山会。', '重阳糕（花糕，层叠登高之意）、菊花酒、柿子。' FROM cultural_item WHERE category = 'festival' AND title = '重阳节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '趵突泉迎春花灯会', '泉城名牌灯会，四十余届薪火相传，万盏花灯映名泉。', '济南趵突泉迎春花灯会始于1979年，是泉城春节期间最具影响力的民俗盛会。灯会以趵突泉公园为舞台，万盏花灯与泉水、假山、亭台相映成趣，''三股水''畔流光溢彩。灯组融合齐风鲁韵、泉城文化与时代主题，辅以猜灯谜、民俗展演等活动，春节期间吸引数十万市民游客观灯。', '济南', NULL, NULL, '["灯会", "泉水文化", "春节"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历正月初一至正月二十前后', '济南元宵赏灯习俗古已有之，1979年趵突泉公园恢复举办迎春花灯会，迄今已举办四十余届。', '赏花灯、猜灯谜、民俗演出、游园观泉。', '灯会期间园内可品油旋、甜沫、冰糖葫芦等济南小吃。' FROM cultural_item WHERE category = 'festival' AND title = '趵突泉迎春花灯会' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '千佛山山会', '自元代延续的古老山会，登高踏青、民俗百戏汇于佛山。', '千佛山山会又称''千佛山庙会''，以农历三月三与九月九两期最盛，尤以九月九重阳山会规模宏大。山会期间，登山主道两侧摊位绵延数里，日用百货、风味小吃、民间工艺琳琅满目，杂技、曲艺、皮影等民俗百戏轮番登场。人们登山礼佛、登高望远、采买山货，是济南人春秋两季的民俗盛事。', '济南', NULL, NULL, '["庙会", "登高", "民俗百戏"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历三月初三、九月初九', '千佛山古称历山，相传舜耕于此。山会习俗自元代形成，明清时期已成规模，延续七百余年。', '登山礼佛、赶会购物、看民间杂耍曲艺、重阳登高。', '山会上可尝到山楂糕、糖葫芦、煎饼卷大葱等风味小吃。' FROM cultural_item WHERE category = 'festival' AND title = '千佛山山会' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '泰山东岳庙会', '因泰山信仰而兴的千年庙会，融祭祀、商贸、游艺于一体。', '泰山东岳庙会依托岱庙而生，历史上以东岳大帝诞辰（农历三月二十八）为正会期。旧时香客自四面八方登泰山、拜岱庙，沿途商贸云集、百戏杂陈，形成''香火最盛处，百货辐辏地''的盛况。今日庙会以岱庙为中心，展示泰山皮影、桃木雕刻、民间曲艺等非遗项目，成为体验泰山民俗文化的重要窗口。', '泰安', NULL, NULL, '["庙会", "泰山信仰", "非遗"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历三月二十八（东岳大帝诞辰）前后', '源于历代帝王封禅泰山与民间东岳大帝信仰，唐宋时期岱庙祭祀活动兴盛，庙会随之形成并延续千年。', '岱庙进香、登山祈福、观非遗展演、购泰山特产。', '泰山煎饼、范镇火烧、泰山三美（白菜、豆腐、水）。' FROM cultural_item WHERE category = 'festival' AND title = '泰山东岳庙会' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '泰山国际登山节', '现代节庆与古老登山传统结合，万人竞攀东岳之巅。', '泰山国际登山节创办于1987年，每年9月在泰安举行，是国内历史最久的登山主题节庆之一。登山节以泰山国际登山比赛为核心，运动员与登山爱好者自红门起跑、勇攀十八盘，直达玉皇顶。节会期间同步举办文化旅游、经贸洽谈、民俗展演等活动，让古老的泰山登山传统焕发现代活力。', '泰安', NULL, NULL, '["登山", "现代节庆", "体育"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年9月', '泰山登高传统由来已久，1987年泰安市创办国际登山节，将民俗登高与现代体育赛事相结合。', '登山比赛、全民健身登泰山、文化展演、经贸活动。', '登山沿途可品泰山女儿茶、煎饼卷大葱、泰山赤鳞鱼（名贵特产）。' FROM cultural_item WHERE category = 'festival' AND title = '泰山国际登山节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '中国（曲阜）国际孔子文化节', '纪念至圣先师的国际性文化盛典，祭孔大典庄严肃穆。', '中国（曲阜）国际孔子文化节创办于1984年，每年9月28日孔子诞辰前后在孔子故里曲阜举行。节庆核心是曲阜孔庙祭孔大典：乐舞告祭、敬献花篮、恭读祭文，依古制行释奠礼，海内外嘉宾与孔氏后裔共祭先师。节会还举办联合国教科文组织孔子教育奖颁奖、儒学论坛、六艺体验等活动，已成为具有国际影响力的文化名片。', '济宁', NULL, NULL, '["祭孔", "儒家文化", "国际节庆"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年9月26日至10月10日（9月28日孔子诞辰祭孔大典）', '祭孔始于公元前478年鲁哀公诔孔，历代相沿成制；1984年曲阜创办孔子诞辰故里游活动，1989年定名国际孔子文化节。', '祭孔大典（释奠礼、八佾舞）、诵读论语、六艺体验、儒学研讨。', '孔府宴（诗礼银杏、带子上朝等孔府菜）、曲阜熏豆腐。' FROM cultural_item WHERE category = 'festival' AND title = '中国（曲阜）国际孔子文化节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '梁山水浒文化节', '八百里水泊遗风犹存，水浒故里再现好汉豪情。', '梁山因《水浒传》名扬天下，梁山水浒文化节以水浒文化为主题，依托水泊梁山景区举办。节会期间，忠义堂前好汉迎宾、武术展演、山东快书、斗鸡斗羊等民俗活动精彩纷呈，游客可体验大块吃肉、大碗喝酒的水浒豪情，观看《好汉迎宾》等实景演出，感受八百里水泊的千年遗韵。', '济宁', NULL, NULL, '["水浒文化", "武术", "实景演出"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年秋季', '北宋宋江起义曾以梁山泊为根据地，元末明初《水浒传》使梁山声名远播，当代梁山以节庆形式传承水浒文化。', '好汉迎宾、武术展演、山东快书、斗鸡斗羊、水浒情景体验。', '梁山糟鱼、大块牛肉、武大郎炊饼配潘金莲咸菜（水浒主题美食）。' FROM cultural_item WHERE category = 'festival' AND title = '梁山水浒文化节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '微山湖荷花节', '十万亩荷花映日盛放，北方水乡的夏日盛会。', '微山湖是北方最大的淡水湖，湖区内十万亩野生荷花蔚为壮观。每年盛夏荷花盛开之际，微山县举办荷花节，游客乘游船穿行荷荡，赏''接天莲叶无穷碧''的湖上胜景。节会融合渔家婚礼表演、渔鹰捕鱼展示、端鼓腔曲艺等湖区民俗，还可品尝全鱼宴、荷花宴等渔家美食，尽显北方水乡风情。', '济宁', NULL, NULL, '["荷花", "湖区民俗", "生态"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年7月至8月', '微山湖荷花观赏传统久远，当地依托十万亩野生荷资源创办荷花节，迄今已举办多届。', '乘船赏荷、观渔家婚礼与渔鹰捕鱼、听端鼓腔、采莲体验。', '微山湖全鱼宴、荷花宴、咸鸭蛋、四鼻鲤鱼。' FROM cultural_item WHERE category = 'festival' AND title = '微山湖荷花节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '菏泽国际牡丹文化旅游节', '曹州牡丹甲天下，谷雨三朝看牡丹。', '菏泽古称曹州，牡丹栽培始于隋、兴于唐宋、盛于明清，现有九大色系、十大花型、一千多个品种，是世界上面积最大、品种最多的牡丹生产基地。民谚云''谷雨三朝看牡丹''，每年4月牡丹盛开，菏泽国际牡丹文化旅游节如期而至，曹州牡丹园、百花园、古今园游人如织。节会期间还举办书画展、非遗展演、经贸洽谈等活动。', '菏泽', NULL, NULL, '["牡丹", "赏花", "曹州文化"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年4月（谷雨前后牡丹盛花期）', '曹州牡丹栽培史逾千年，明清时已有''曹州牡丹甲海内''之誉；1992年起菏泽定期举办牡丹花会，后升级为国际牡丹文化旅游节。', '赏牡丹、牡丹书画展、摄影采风、非遗展演。', '牡丹花蕊茶、牡丹糕、单县羊肉汤、曹州耿饼。' FROM cultural_item WHERE category = 'festival' AND title = '菏泽国际牡丹文化旅游节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '东昌府葫芦文化艺术节', '千年福禄之乡，小葫芦雕出大乾坤。', '聊城种植葫芦的历史可追溯到宋代，东昌葫芦雕刻是国家级非物质文化遗产，以针刻、片花等技法在葫芦上刻画戏曲人物、花鸟虫鱼，玲珑剔透。葫芦谐音''福禄''，寓意吉祥。每年秋季葫芦成熟，东昌府区举办葫芦文化艺术节，集中展示雕刻葫芦、范制葫芦、烙画葫芦等精品，葫芦大集上万商云集，成为全国葫芦文化的交流中心。', '聊城', NULL, NULL, '["葫芦雕刻", "非遗", "福禄文化"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年秋季（葫芦收获季）', '聊城葫芦种植与雕刻技艺自宋代传承至今，东昌葫芦雕刻2008年入选国家级非遗名录，当地据此创办葫芦文化节。', '葫芦精品展、雕刻技艺展演、葫芦大集、福禄文化体验。', '节会期间可尝魏氏熏鸡、沙镇呱嗒等聊城名吃。' FROM cultural_item WHERE category = 'festival' AND title = '东昌府葫芦文化艺术节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '东阿阿胶冬至滋补节', '冬至子时取阿井水、燃桑柴火，千年炼胶仪式重现。', '阿胶以山东东阿县所产最为道地，两千多年来被视为滋补上品。传统炼胶讲究冬至子时取阿井之水、燃桑木之火、用乌驴之皮，历时数十日方成。每年冬至，东阿举办阿胶滋补文化节，重现古法炼胶取水仪式，展示炼胶技艺，传播中医药滋补养生文化，吸引众多中医药爱好者与游客参与。', '聊城', NULL, NULL, '["阿胶", "中医药", "冬至"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年冬至前后', '东阿阿胶制作技艺有两千多年历史，《神农本草经》已将阿胶列为上品；当地依冬至炼胶古俗创办滋补文化节。', '冬至取水仪式、古法炼胶展示、滋补养生文化体验。', '阿胶糕、阿胶枣、东阿黄河鲤鱼。' FROM cultural_item WHERE category = 'festival' AND title = '东阿阿胶冬至滋补节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '宁津蟋蟀文化节', '中华蟋蟀第一县，秋兴虫风千年不衰。', '宁津蟋蟀以体魄雄健、骁勇善斗闻名，历史上曾作为贡品进献宫廷，有''宁津蟋蟀斗天下''之说。当地斗蟋蟀习俗自唐宋延续至今，1991年宁津被命名为''中华蟋蟀第一县''。每年秋季，宁津举办蟋蟀文化节，各地虫友携名虫汇聚，捉虫、养虫、斗虫系列民俗活动与蟋蟀交易大集同步展开，独具鲁北风情。', '德州', NULL, NULL, '["蟋蟀", "斗虫民俗", "鲁北风情"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年8月至9月（蟋蟀旺季）', '宁津斗蟋习俗源于唐宋斗虫之风，明清时宁津蟋蟀已列为贡品，当代以文化节形式延续这一独特民俗。', '蟋蟀捕捉体验、斗蟋比赛、虫具展示交易、蟋蟀文化研讨。', '节会期间可品宁津保店驴肉、长官包子等当地名吃。' FROM cultural_item WHERE category = 'festival' AND title = '宁津蟋蟀文化节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '乐陵金丝小枣文化节', '千年枣林披红挂金，金丝小枣甜透金秋。', '乐陵金丝小枣栽培始于商周、兴于魏晋、盛于明清，以皮薄肉厚、核小味甜、掰开可见金丝粘连而得名。乐陵拥有百万亩枣林，其中千年以上古枣树千余株。每年9月小枣成熟，乐陵举办金丝小枣文化节，游客穿行千年枣林采摘小枣，观枣乡民俗展演，体验打枣、晒枣的农事乐趣。', '德州', NULL, NULL, '["小枣", "采摘", "枣乡民俗"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年9月（小枣成熟季）', '乐陵枣树栽培史逾三千年，金丝小枣清代列为贡品；当地依托千年枣林资源创办小枣文化节。', '枣林采摘、打枣体验、枣乡民俗展演、枣产品展销。', '金丝小枣、枣花蜜、枣脯、枣木杠子酒（枣木杠烧酒）。' FROM cultural_item WHERE category = 'festival' AND title = '乐陵金丝小枣文化节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '齐文化节', '故都临淄溯齐风，蹴鞠故里话春秋。', '淄博临淄是春秋五霸之首、战国七雄之一的齐国故都，也是世界足球起源地（蹴鞠）。齐文化节以传承弘扬齐文化为宗旨，在临淄举行祭姜大典（祭祀齐国始祖姜太公）、齐文化学术研讨、蹴鞠表演、齐风民乐演出等活动。管仲纪念馆、齐故城遗址、足球博物馆等场馆联动开放，让泱泱齐风可感可触。', '淄博', NULL, NULL, '["齐文化", "蹴鞠", "故都"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年9月', '临淄作为齐国都城长达八百余年，2004年临淄被国际足联确认为世界足球起源地；当地创办齐文化节传承齐文化。', '祭姜大典、蹴鞠展演、编钟齐乐演出、遗址研学。', '淄博烧烤、周村烧饼、博山菜（豆腐箱、酥锅）。' FROM cultural_item WHERE category = 'festival' AND title = '齐文化节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '周村芯子', '凌空而立的民间绝活，旱码头元宵扮玩的压轴大戏。', '周村芯子是流传于淄博周村的民间扮玩艺术，演员（多为孩童）被缚于数米高的铁制芯子上，凌空扮作戏曲人物，远远望去如悬空而立、惊险绝伦，2008年入选国家级非物质文化遗产。周村自古为旱码头、商埠重镇，每逢元宵佳节，芯子与龙灯、高跷、旱船等组成盛大扮玩队伍走街串巷，万人空巷。', '淄博', NULL, NULL, '["芯子", "元宵扮玩", "国家级非遗"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '农历正月十四至十六', '周村芯子起源于明清时期周村商埠的元宵扮玩活动，由''抬阁''艺术演变而来，迄今已有四百余年历史。', '芯子巡游、龙灯高跷旱船扮玩、猜灯谜、逛古商城。', '周村烧饼、煮锅、五香羊肉。' FROM cultural_item WHERE category = 'festival' AND title = '周村芯子' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '中国（惠民）孙子文化节', '兵圣故里祭孙武，千年兵法耀古今。', '滨州惠民县是兵圣孙武的故里。孙子文化节以弘扬孙子兵法智慧为主题，在中国孙子兵法城举行祭祀兵圣大典，并举办孙子文化论坛、兵法智慧讲座、古代战阵演练等活动。孙子兵法城以秦汉式建筑群再现兵圣传奇，节会期间武定府衙、渤海革命老区纪念园等联动开放，成为研学兵法文化的重要平台。', '滨州', NULL, NULL, '["孙子兵法", "兵圣", "研学"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年10月', '孙武为春秋末期齐国乐安（今惠民一带）人，《孙子兵法》被誉为兵学圣典；惠民依托兵圣故里品牌创办孙子文化节。', '祭兵圣大典、兵法论坛、战阵演练、兵法城研学。', '魏集驴肉、青阳炒鸡、锅子饼（滨州名吃）。' FROM cultural_item WHERE category = 'festival' AND title = '中国（惠民）孙子文化节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '沾化冬枣节', '冬枣之乡硕果盈枝，盐碱地上长出的甜蜜产业。', '沾化地处黄河三角洲腹地，独特的盐碱水土孕育出皮薄脆甜、营养丰富的沾化冬枣，被誉为''中华果王''。每年10月冬枣成熟，沾化举办冬枣节，游客可深入冬枣园采摘尝鲜，参加枣王评选、冬枣擂台赛等活动。小小冬枣已成为带动当地农民增收的支柱产业，冬枣节也成为展示黄河三角洲生态农业的窗口。', '滨州', NULL, NULL, '["冬枣", "采摘", "生态农业"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年10月（冬枣成熟季）', '沾化冬枣栽培历史悠久，当地自上世纪九十年代规模化种植并创办冬枣节，打响了沾化冬枣品牌。', '冬枣采摘、枣王评选、农产品展销、黄河口生态游。', '沾化冬枣、枣花蜜、黄河口大闸蟹（时令）。' FROM cultural_item WHERE category = 'festival' AND title = '沾化冬枣节' LIMIT 1;
INSERT INTO cultural_item (category, title, summary, content, region, image_url, image_anime_url, tags, sort_order, status, source) VALUES ('festival', '黄河口（东营）国际观鸟节', '候鸟翔集黄河口，湿地观鸟正当时。', '黄河三角洲国家级自然保护区地处东亚-澳大利西亚候鸟迁徙通道，每年有数百万只候鸟在此停歇、越冬，包括东方白鹳、丹顶鹤、大天鹅等珍稀鸟类，被誉为''鸟类的国际机场''。冬季候鸟迁徙高峰，东营举办黄河口国际观鸟节，组织观鸟比赛、生态摄影、湿地科普等活动，让人们在大河之洲感受万鸟翔集的生态奇观。', '东营', NULL, NULL, '["观鸟", "湿地", "黄河口生态"]', 0, 'draft', 'ai');
INSERT INTO festival_detail (item_id, festival_date, origin, customs, food) SELECT id, '每年冬季候鸟迁徙期', '黄河三角洲是新生湿地生态系统，鸟类资源极为丰富；东营依托这一生态优势创办观鸟节，传播生态文明理念。', '观鸟比赛、生态摄影、湿地科普研学、观鸟大赛。', '黄河口大闸蟹、黄河刀鱼（时令）、利津水煎包。' FROM cultural_item WHERE category = 'festival' AND title = '黄河口（东营）国际观鸟节' LIMIT 1;
